using Microsoft.Extensions.AI;
using System.ComponentModel;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(' ', args) : "the impact of quantum computing on cryptography";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the AI chat client with tool support
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT") ?? "https://api.openai.com/v1";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException("Set OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Create tool instances
var searchTool = new WebSearchTool();
var notesTool = new NotesTool();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(searchTool.Search),
        AIFunctionFactory.Create(notesTool.AddNote),
        AIFunctionFactory.Create(notesTool.GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Taking notes on key findings using the note-taking tool
        3. After gathering enough information, retrieve all your notes and provide a comprehensive summary

        Always take notes on important findings before summarizing.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

// Run the agent loop
var response = await client.GetResponseAsync(messages, chatOptions);
Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

// Display collected notes
var notes = notesTool.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===");
    for (int i = 0; i < notes.Count; i++)
        Console.WriteLine($"  {i + 1}. {notes[i]}");
}

// --- Tool Definitions ---

public class WebSearchTool
{
    private static readonly HttpClient _http = new();

    [Description("Searches the web for information on a given query. Returns relevant search result snippets.")]
    public async Task<string> Search([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");
        try
        {
            // Use a public search API (DuckDuckGo instant answer)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await _http.GetStringAsync(url);
            var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Extract abstract
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"Summary: {abstractText}");

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                        results.Add(text.GetString() ?? "");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

public class NotesTool
{
    private readonly List<string> _notes = new();

    [Description("Adds a research note to the collection. Use this to record important findings.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public List<string> GetAllNotes() => _notes;
}

